DELETE FROM RECENT_PLACES
WHERE userId = #{userId}
  AND recentPlaceId NOT IN (
    SELECT recentPlaceId
    FROM (
        SELECT recentPlaceId
        FROM RECENT_PLACES
        WHERE userId = #{userId}
        ORDER BY searchedAt DESC, recentPlaceId DESC
        LIMIT 10
    ) recentKeep
  )

